def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """A more accurate version of the equation using a fourth-order polynomial and interaction coefficients."""

    a, b, c, d, e, f, g, h = parameters[0], parameters[1], parameters[2], parameters[3], parameters[4], parameters[5], parameters[6], parameters[7]
    return a + b * gate_voltage_abs + c * drain_voltage_abs + d * (gate_voltage_abs ** 2) + e * (drain_voltage_abs ** 2) + g * gate_voltage_abs * drain_voltage_abs + h * (gate_voltage_abs ** 2) * (drain_voltage_abs ** 2)
